form.onsubmit=async e=>{e.preventDefault();const c=readForm();if(!autoRegistration&&editingNumber===null)c.isChecked=true;const dup=master.characters.find(x=>x.encyclopediaNumber===c.encyclopediaNumber&&x.encyclopediaNumber!==editingNumber);const swapping=!!dup&&editingNumber!==null&&editingNumber!==c.encyclopediaNumber;if(swapping){if(!await confirmCharacterSave(`No.${editingNumber}「${c.officialName}」と No.${c.encyclopediaNumber}「${dup.officialName}」の図鑑番号を入れ替えます。両方のキャラデータは残ります。入れ替えますか？`))return;}else if(dup&&!await confirmCharacterSave(`No.${c.encyclopediaNumber} は登録済みです。上書きしますか？`))return;if(c.imageData&&location.hostname==="127.0.0.1"){try{const response=await fetch("http://127.0.0.1:8771/save-image",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({number:c.encyclopediaNumber,data:c.imageData}),signal:AbortSignal.timeout(5000)});if(response.ok){c.imageFile=(await response.json()).imageFile;c.imageData="";}}catch{ /* サービス停止時も画像データごと保存して登録を続ける。 */ }}if(swapping){c.evolutionGroupNumbers=nums(val("evolutionGroupNumbers"));const oldNumber=editingNumber,newNumber=c.encyclopediaNumber;dup.encyclopediaNumber=oldNumber;master.characters=master.characters.filter(x=>x===dup||x.encyclopediaNumber!==oldNumber);master.characters.push(c);for(const item of master.characters){const group=item.evolutionGroupNumbers||[];item.evolutionGroupNumbers=[...new Set((item===c?group:group.map(n=>n===oldNumber?newNumber:n===newNumber?oldNumber:n)).concat(item.encyclopediaNumber))].sort((a,b)=>a-b);}}else{master.characters=master.characters.filter(x=>x.encyclopediaNumber!==editingNumber&&x.encyclopediaNumber!==c.encyclopediaNumber);master.characters.push(c);}if(!await save()){toast("端末内に保存しましたが共有DBへの送信は未完了です。");return}if(editingNumber!==null){location.assign("character-list.html");return;}render();clearEditor();toast(`No.${c.encyclopediaNumber} を保存しました。`)};
