// Serialize edits across registration tabs; never replace an in-progress form.
function sharedEdit(handler){return event=>{event?.preventDefault();return navigator.locks.request(STORAGE_KEY,()=>{master=loadMaster();master.friendshipCatalog||=[];return handler(event)}).catch(error=>{console.error(error);alert("保存できませんでした。入力内容は残っています。")})}}
