// Local files are embedded in the character record, so tabs and JSON exports share them.
const imageStatus=document.getElementById('characterImageStatus');
const imageFileControl=document.getElementById('characterImageFile');
async function selectCharacterImage(file){
 const version=++imageReadVersion;
 if(!file||!['image/png','image/jpeg','image/jpg','image/webp','image/gif'].includes(file.type)){imageStatus.textContent='PNG・JPEG・WebP・GIFの画像を選んでください。';return;}
 if(file.size>1024*1024){imageStatus.textContent='画像は1MB以下のファイルを選んでください。';return;}
 imageFileControl.setCustomValidity('画像を読み込み中です。');
 try{
  const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});
  if(version!==imageReadVersion)return;
  set('imageRemoved','');set('imageUrl','');set('imageData',data);updateCharacterPreview();imageStatus.textContent='画像を選択しました。「このキャラを保存」で確定します。';
 }catch{if(version===imageReadVersion)imageStatus.textContent='画像を読み込めませんでした。別の画像を選んでください。';}
 finally{if(version===imageReadVersion)imageFileControl.setCustomValidity('');}
}
imageFileControl.onchange=e=>selectCharacterImage(e.target.files[0]);
document.getElementById('clearCharacterImage').onclick=()=>{imageReadVersion++;set('imageData','');imageFileControl.value='';imageFileControl.setCustomValidity('');updateCharacterPreview();imageStatus.textContent='選択画像を解除しました。既存の対応画像があれば表示します。';};
form.addEventListener('reset',()=>{imageReadVersion++;imageFileControl.setCustomValidity('');imageStatus.textContent='画像はファイルから選択して、「このキャラを保存」で確定します。';});

document.getElementById('removeCharacterImage').onclick=()=>{imageReadVersion++;set('imageRemoved','1');set('imageData','');set('imageFile','');set('imageUrl','');imageFileControl.value='';imageFileControl.setCustomValidity('');updateCharacterPreview();imageStatus.textContent='画像なしにしました。「このキャラを保存」で確定します。';};

// 画像保存サービスがあとから復旧しても、退避中の画像を自動で図鑑番号.pngへ移す。
async function syncDeferredImages(){
  if(!master.characters.some(character=>character.imageData&&character.encyclopediaNumber))return;
  try{
    await navigator.locks.request(STORAGE_KEY,async()=>{
      master=loadMaster();master.friendshipCatalog||=[];
      let changed=false;
      for(const character of master.characters){
        if(!character.imageData||!character.encyclopediaNumber)continue;
        try{
          const response=await fetch("http://127.0.0.1:8771/save-image",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({number:character.encyclopediaNumber,data:character.imageData}),signal:AbortSignal.timeout(5000)});
          if(!response.ok)break;
          character.imageFile=(await response.json()).imageFile;
          character.imageData="";
          changed=true;
        }catch{break}
      }
      if(changed)save();
    });
  }catch(error){console.warn("画像の自動同期を保留しました",error)}
}
syncDeferredImages();
setInterval(syncDeferredImages,30000);

// 補修キューは画面を切り替えずに取り込む。手動入力中のフォームには触れない。
function mergeRepairValue(current, patch){
 if(Array.isArray(patch))return patch;
 if(patch&&typeof patch==="object"){
  const base=current&&typeof current==="object"&&!Array.isArray(current)?current:{};
  const merged={...base};
  for(const [key,value] of Object.entries(patch))merged[key]=mergeRepairValue(base[key],value);
  return merged;
 }
 return patch;
}
let appliedRepairRevision="";
async function applyBackgroundRepairQueue(){
 try{
  const response=await fetch(`auto-repair-queue.json?t=${Date.now()}`,{cache:"no-store"});
  if(!response.ok)return;
  const queue=await response.json();
  if(!queue?.revision||queue.revision===appliedRepairRevision)return;
  await navigator.locks.request(STORAGE_KEY,()=>{
   master=loadMaster();master.friendshipCatalog||=[];
   for(const patch of queue.patches||[]){
    const index=master.characters.findIndex(item=>item.encyclopediaNumber===Number(patch.encyclopediaNumber));
    if(index>=0)master.characters[index]=mergeRepairValue(master.characters[index],patch.changes||{});
   }
   save();
  });
  appliedRepairRevision=queue.revision;
 }catch(error){console.warn("補修キューの取り込みを保留しました",error)}
}
if(!window.SharedMasterStore?.enabled){applyBackgroundRepairQueue();setInterval(applyBackgroundRepairQueue,2000);}

function confirmCharacterSave(message){
 return new Promise(resolve=>{
  const modal=document.createElement('dialog');
  modal.setAttribute('aria-label','保存内容の確認');
  modal.style.cssText='max-width:520px;width:calc(100% - 48px);padding:24px;border:2px solid #527a65;border-radius:16px;color:#18362a;background:white;box-shadow:0 16px 80px #0006';
  const title=document.createElement('h2');title.textContent='保存内容の確認';
  const text=document.createElement('p');text.textContent=message;text.style.lineHeight='1.8';
  const actions=document.createElement('div');actions.style.cssText='display:flex;gap:12px;justify-content:flex-end;margin-top:24px';
  const cancel=document.createElement('button');cancel.type='button';cancel.textContent='キャンセル';
  const accept=document.createElement('button');accept.type='button';accept.className='primary';accept.textContent='確定して保存';
  const finish=value=>{modal.close();modal.remove();resolve(value)};
  cancel.onclick=()=>finish(false);accept.onclick=()=>finish(true);
  modal.oncancel=event=>{event.preventDefault();finish(false)};
  actions.append(cancel,accept);modal.append(title,text,actions);document.body.append(modal);modal.showModal();accept.focus();
 });
}






